package com.example.cvd;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
class MetrologyValidationTest {
 final ObjectMapper mapper=new ObjectMapper();
 ObjectNode result(){var r=mapper.createObjectNode();r.put("seed","a".repeat(64));r.put("modelVersion","synthetic-kla-v1").put("synthetic",true).put("diameterMm",300).put("edgeExclusionMm",3).put("coordinates","center-x-right-y-up-notch-down-mm").put("meanNm",10).put("minNm",10).put("maxNm",10).put("uniformityPct",0).put("defectCountLimit",10).put("defectSizeLimitUm",1).put("thicknessQuality","pass").put("defectQuality","pass").put("quality","pass");var s=r.putObject("source");s.put("equipmentId",Equipment.FIRST).put("waferId","w1").put("lotId","l1").put("slot",1).put("pm","PM1").put("processRunId","run1").put("recipeVersion","v1").put("thicknessNm",10).put("targetThicknessNm",10).put("thicknessTolerancePct",10).put("uniformityLimitPct",5);var samples=s.putArray("sampleThicknessNm");for(int i=0;i<5;i++)samples.add(10);var points=r.putArray("points");for(int i=0;i<49;i++)points.addObject().put("x",i).put("y",0).put("thicknessNm",10);r.putArray("defects");return r;}
 @Test void validAndCorrupt(){var r=result();assertTrue(MetrologyApi.validResult(r,r.path("source")));r.put("meanNm",11);assertFalse(MetrologyApi.validResult(r,r.path("source")));r=result();((ArrayNode)r.get("points")).remove(0);assertFalse(MetrologyApi.validResult(r,r.path("source")));r=result();((ObjectNode)r.path("points").get(0)).put("x",Double.NaN);assertFalse(MetrologyApi.validResult(r,r.path("source")));r=result();((ObjectNode)r.path("points").get(0)).put("x",148);assertFalse(MetrologyApi.validResult(r,r.path("source")));}
 @Test void sourceMismatchAndDefects(){var r=result();var s=r.path("source").deepCopy();((ObjectNode)s).put("waferId","other");assertFalse(MetrologyApi.validResult(r,s));var d=((ArrayNode)r.get("defects")).addObject();d.put("defectId","d1").put("type","particle").put("x",0).put("y",0).put("sizeUm",2);assertFalse(MetrologyApi.validResult(r,r.path("source")));r.put("defectQuality","review").put("quality","review");assertTrue(MetrologyApi.validResult(r,r.path("source")));((ArrayNode)r.get("defects")).add(d.deepCopy());assertFalse(MetrologyApi.validResult(r,r.path("source")));}
 @Test void differentEquipmentKeys(){assertNotEquals(MetrologyApi.key(Equipment.FIRST,"w","run"),MetrologyApi.key(Equipment.IDS.get(1),"w","run"));assertFalse(Equipment.IDS.contains(MetrologyApi.STATION));}
}
